/**
 * The API, typed from the server's own OpenAPI schema.
 *
 * `schema.d.ts` is generated by `npm run gen:types` from openapi.json, which
 * FastAPI derives from the Pydantic models — so a change to a response shape
 * becomes a TypeScript error here rather than a runtime surprise in the
 * browser.
 *
 * Every request sends the session cookie, which is how the server knows whose
 * project and conversation these are.
 */
import type { components } from './schema'

type Schemas = components['schemas']

export type Session = Schemas['SessionModel']
export type Project = Schemas['ProjectModel']
export type ProjectInfo = Schemas['ProjectInfoModel']
export type Test = Schemas['TestModel']
export type Setup = Schemas['SetupModel']
export type MethodList = Schemas['MethodListModel']
export type Method = Schemas['MethodModel']
export type TestType = Schemas['TestTypeModel']
export type PreparedData = Schemas['PreparedDataModel']
export type Validation = Schemas['ValidationModel']
export type Diagnosis = Schemas['DiagnosisModel']
export type Result = Schemas['ResultModel']
export type Parameter = Schemas['ParameterModel']
export type ManualMatch = Schemas['ManualMatchModel']
export type Comparison = Schemas['ComparisonModel']
export type ComparisonRow = Schemas['ComparisonRowModel']
export type ChatState = Schemas['ChatStateModel']
export type ChatMessage = Schemas['MessageModel']
export type Suggestion = Schemas['SuggestionModel']
export type RetrievedDoc = Schemas['RetrievedDocModel']
export type AnalysisRun = Schemas['AnalysisRunModel']
export type OCRTable = Schemas['OCRTableModel']
export type OCRCell = Schemas['OCRCellModel']

/** An error the server explained. `detail` is written for the user to read. */
export class ApiError extends Error {
  readonly status: number

  constructor(status: number, detail: string) {
    super(detail)
    this.name = 'ApiError'
    this.status = status
  }
}

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  let response: Response
  try {
    response = await fetch(path, { credentials: 'include', ...init })
  } catch {
    throw new ApiError(0, 'Cannot reach the server. Check that it is running.')
  }

  if (!response.ok) {
    throw new ApiError(response.status, await detailOf(response))
  }
  if (response.status === 204) return undefined as T
  return (await response.json()) as T
}

async function detailOf(response: Response): Promise<string> {
  try {
    const body = await response.json()
    const detail = body?.detail
    if (typeof detail === 'string') return detail
    // FastAPI's validation errors arrive as a list of field problems.
    if (Array.isArray(detail) && detail.length > 0) {
      return detail.map((d: { msg?: string }) => d.msg ?? '').join('; ')
    }
  } catch {
    /* fall through to the status text */
  }
  return response.statusText || `Request failed (${response.status})`
}

function json<T>(path: string, method: string, body?: unknown): Promise<T> {
  return request<T>(path, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  })
}

function upload<T>(path: string, file: File): Promise<T> {
  const form = new FormData()
  form.append('file', file)
  return request<T>(path, { method: 'POST', body: form })
}

/** A file the browser saves, e.g. the project or the report. */
/** A response read as text rather than parsed. The project file is JSON, but
 * autosave keeps the server's own bytes so that restoring re-uploads exactly
 * what Save would have written. */
async function requestText(path: string): Promise<string> {
  let response: Response
  try {
    response = await fetch(path, { credentials: 'include' })
  } catch {
    throw new ApiError(0, 'Cannot reach the server. Check that it is running.')
  }
  if (!response.ok) throw new ApiError(response.status, await detailOf(response))
  return response.text()
}

/**
 * A streamed answer: tokens as they are written, then the whole chat state.
 *
 * Server-sent events over `fetch`, rather than `EventSource`, for two reasons —
 * the request is a POST with a body, which EventSource cannot make, and this
 * carries the session cookie the same way every other call does.
 *
 * It falls back to the ordinary route whenever streaming cannot be used: an old
 * browser without ReadableStream, a proxy that buffers the response into one
 * piece, or any error before the first token. Nothing is lost by falling back —
 * the server stores the same conversation either way — so the caller gets a
 * complete answer and at worst waits for it as before.
 */
/** What separates one server-sent event from the next, and its lines. */
const NEWLINE = '\n'
const BLANK_LINE = '\n\n'

async function streamChat(message: string,
                          onToken: (text: string) => void): Promise<ChatState> {
  let response: Response
  try {
    response = await fetch('/api/chat/messages/stream', {
      method: 'POST',
      credentials: 'include',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ message }),
    })
  } catch {
    throw new ApiError(0, 'Cannot reach the server. Check that it is running.')
  }

  if (!response.ok) throw new ApiError(response.status, await detailOf(response))
  if (!response.body) {
    // No readable stream here: ask again the ordinary way rather than fail.
    return json<ChatState>('/api/chat/messages', 'POST', { message })
  }

  const reader = response.body.getReader()
  const decoder = new TextDecoder()
  let buffer = ''
  let state: ChatState | null = null
  let failure = ''

  // Events are separated by a blank line; a chunk can split one anywhere, so the
  // tail of the buffer is kept until its terminator arrives.
  for (;;) {
    const { value, done } = await reader.read()
    if (value) buffer += decoder.decode(value, { stream: true })
    let cut = buffer.indexOf(BLANK_LINE)
    while (cut !== -1) {
      const frame = buffer.slice(0, cut)
      buffer = buffer.slice(cut + 2)
      const line = frame.split(NEWLINE).find((part) => part.startsWith('data: '))
      if (line) {
        const event = JSON.parse(line.slice(6)) as {
          type: string; text?: string; detail?: string; state?: ChatState
        }
        if (event.type === 'token' && event.text) onToken(event.text)
        else if (event.type === 'state' && event.state) state = event.state
        else if (event.type === 'error') failure = event.detail ?? 'The consultant failed.'
      }
      cut = buffer.indexOf(BLANK_LINE)
    }
    if (done) break
  }

  if (failure) throw new ApiError(502, failure)
  // The stream ended without the closing state — a dropped connection, say. The
  // turn may well have completed on the server, so read the conversation rather
  // than guess at it.
  return state ?? request<ChatState>('/api/chat')
}

async function download(path: string, fallbackName: string): Promise<void> {
  const response = await fetch(path, { credentials: 'include' })
  if (!response.ok) throw new ApiError(response.status, await detailOf(response))

  const blob = await response.blob()
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filenameFrom(response) ?? fallbackName
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  URL.revokeObjectURL(url)
}

function filenameFrom(response: Response): string | null {
  const header = response.headers.get('content-disposition') ?? ''
  const match = header.match(/filename="([^"]+)"/)
  return match ? match[1] : null
}

export const api = {
  // ── Session and catalogue ────────────────────────────────────────────────
  session: () => request<Session>('/api/session'),
  testTypes: () => request<TestType[]>('/api/test-types'),
  // `filtered=false` returns every method for the test type, including those
  // this dataset cannot support — the cards show those greyed, with the reason.
  methods: (testType: string, filtered = true) =>
    request<MethodList>(`/api/methods?test_type=${encodeURIComponent(testType)}`
                        + `&filtered=${filtered}`),

  // ── Project ──────────────────────────────────────────────────────────────
  project: () => request<Project>('/api/project'),
  newProject: () => json<Project>('/api/project/new', 'POST'),
  openProject: (file: File) => upload<Project>('/api/project/open', file),
  saveProject: () => download('/api/project/file', 'project.hydroassist.json'),
  // The same file, as text, for the browser-side autosave.
  projectFile: () => requestText('/api/project/file'),
  updateInfo: (info: ProjectInfo) => json<Project>('/api/project/info', 'PATCH', info),

  addTest: () => json<Project>('/api/tests', 'POST'),
  activateTest: (testId: string) =>
    json<Project>(`/api/tests/${testId}/activate`, 'POST'),
  updateTest: (testId: string, details: Partial<Schemas['TestDetailsModel']>) =>
    json<Project>(`/api/tests/${testId}`, 'PATCH', details),

  // ── Readings ─────────────────────────────────────────────────────────────
  uploadReadings: (testId: string, file: File) =>
    upload<PreparedData>(`/api/tests/${testId}/readings`, file),
  // Same intake, for columns pasted from a spreadsheet rather than saved to a
  // file first. The delimiter is sniffed on the server.
  pasteReadings: (testId: string, text: string) =>
    json<PreparedData>(`/api/tests/${testId}/readings/text`, 'POST', { text }),
  // `rows` is how much of the table to send back: a preview by default, the
  // whole thing when the user opens it to check what was read.
  readings: (testId: string, rows?: number) =>
    request<PreparedData>(`/api/tests/${testId}/readings`
      + (rows ? `?rows=${rows}` : '')),
  // A photograph of a field sheet. Note the return type: a grid to confirm, not
  // readings. Nothing is stored until the corrected grid is pasted back.
  readImage: (testId: string, file: File) =>
    upload<OCRTable>(`/api/tests/${testId}/readings/image`, file),

  // ── Analysis ─────────────────────────────────────────────────────────────
  saveSetup: (testId: string, setup: Setup) =>
    json<Test>(`/api/tests/${testId}/setup`, 'PUT', setup),
  run: (method: string, setup: Setup) =>
    json<Result>('/api/analyses/run', 'POST', { method, setup }),
  currentResult: () => request<Result>('/api/analyses/current'),
  // What has been run this session, saved or not.
  analysisHistory: () => request<AnalysisRun[]>('/api/analyses/history'),
  manualMatch: (T: number, S: number | null) =>
    json<ManualMatch>('/api/analyses/manual-match', 'POST', { T, S }),
  saveAnalysis: () => json<Comparison>('/api/analyses/save', 'POST'),
  comparison: (testId: string) =>
    request<Comparison>(`/api/tests/${testId}/comparison`),
  removeAnalysis: (testId: string, analysisId: string) =>
    json<Comparison>(`/api/tests/${testId}/analyses/${analysisId}`, 'DELETE'),
  report: () => download('/api/report.pdf', 'report.pdf'),

  // ── Chat ─────────────────────────────────────────────────────────────────
  chat: () => request<ChatState>('/api/chat'),
  sendMessage: (message: string) =>
    json<ChatState>('/api/chat/messages', 'POST', { message }),
  // The same turn, with the answer arriving as it is written. Falls back to the
  // plain route by itself, so a browser or proxy that cannot stream still works.
  streamMessage: (message: string, onToken: (text: string) => void) =>
    streamChat(message, onToken),
  confirmMethod: (method: string) =>
    json<ChatState>('/api/chat/confirm', 'POST', { method }),
  resetChat: () => json<ChatState>('/api/chat/reset', 'POST'),
  exportChat: () => download('/api/chat/export', 'hydroassist_chat.txt'),
}
